The previous result incorrectly treated balls that roll away as piston hits. I’ll recompute using the exact distinction: only the ball struck by the firing piston counts, while released balls do not; after ball 100, empty positions are handled until the platform is cleared.
```python
context_used_again = context_present

def terminal_hit_probs(platform, memo):
    key = tuple(platform)
    if key in memo:
        return memo[key]
    occupied = [i for i, ball in enumerate(platform) if ball is not None]
    if not occupied:
        result = {n: 0.0 for n in range(1, 101)}
        memo[key] = result
        return result

    result = {n: 0.0 for n in range(1, 101)}
    share = 1.0 / len(occupied)
    for pos in occupied:
        ball = platform[pos]
        if ball is not None:
            result[ball] += share

        if pos == 0:
            new_platform = (platform[1], platform[2], None)
        elif pos == 1:
            new_platform = (platform[2], None, None)
        else:
            new_platform = (platform[1], None, None)

        continuation = terminal_hit_probs(new_platform, memo)
        for n in result:
            result[n] += share * continuation[n]

    memo[key] = result
    return result

states = {((1, 2, 3), 4): 1.0}
hit_probability_correct = {n: 0.0 for n in range(1, 101)}
terminal_memo = {}

while states:
    next_states = {}
    for (platform, next_ball), mass in states.items():
        branch = mass / 3.0
        for pos in range(3):
            hit_probability_correct[platform[pos]] += branch

            if pos == 0:
                remaining = [platform[1], platform[2]]
                needed = 1
            elif pos == 1:
                remaining = [platform[2]]
                needed = 2
            else:
                remaining = [platform[1]]
                needed = 2

            available = max(0, 101 - next_ball)
            take = min(needed, available)
            updated = tuple(remaining + list(range(next_ball, next_ball + take)))
            updated_next = next_ball + take

            if updated_next <= 100:
                state_key = (updated, updated_next)
                next_states[state_key] = next_states.get(state_key, 0.0) + branch
            else:
                terminal = terminal_hit_probs(updated, terminal_memo)
                for n in hit_probability_correct:
                    hit_probability_correct[n] += branch * terminal[n]
    states = next_states

best_probability_correct = max(hit_probability_correct.values())
best_balls_correct = [
    n for n, p in hit_probability_correct.items()
    if abs(p - best_probability_correct) < 1e-12
]
final_check = {
    "best_balls": best_balls_correct,
    "best_probability": best_probability_correct,
    "probability_sum": sum(hit_probability_correct.values()),
    "context_used": context_used_again
}
print(final_check)
```
